scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    //				return false;
    return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var data = eval("scwin.data" + selectbox1.getValue());
    dataList1.setData(data.slice(0));
}
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_groupbyFilterBoxFormatter = function(data) {
    console.log(data);
    var label = "";
    var labelArr = [];
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        debugger;
        for (var j = 0; j < filter.length; j++) {
            if (filter[j].gate)
                s_label = s_label + " " + filter[j].gate + " ";
            var values = filter[j].values;
            if (values.join)
                values = "[" + values.join(" ,") + "]";
            s_label = s_label + filter[j].operator + " " + values;
        }
        s_label = "(" + header + " " + s_label + ")";
        labelArr.push(s_label);
    }
    label = labelArr.join(" & ");
    console.log('label:' + label);
    return label;
};
scwin.trigger2_onclick = function(e) {
    grid1.setColumnVisible("col1", false);
};
scwin.setVal = function() {
    before = WebSquare.wUnit.getDomById($p.id + 'grid1_foot_table').getBoundingClientRect().y;
}
scwin.setVal2 = function() {
    after = WebSquare.wUnit.getDomById($p.id + 'grid1_foot_table').getBoundingClientRect().y;
}
scwin.checkVal = function() {
    return before == after;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 하단의 'setColumn'버튼을 클릭하여 groupbyFilterBox의 위치가 동일하게 유지되는지를 확인한다.
    //1. After running the sample, click the 'setColumn' button at the bottom to check whether the position of the groupbyFilterBox is the same.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    //Verify step 1. setColumnvisible() API를 실행해도 동일하게 유지된다.(이전에는 아래로 내려가는 현상이 발생함)
    //1. The setColumnvisible () API will remain the same (it will go down before)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 12-Feb-2018
    window.before = 0;
    window.after = 0;
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
